tool_input.command:
node --input-type=module -e "
import { handle } from './src/api.js';
import { dueReminders } from './src/scheduler.js';
const r = handle({ method: 'POST', path: '/reminders', body: { userId: 'u1', text: 'tea', at: '2026-03-01T09:00', tzOffsetMin: 330 } }).body;
console.log('stored due_ms (UTC):', new Date(r.due_ms).toISOString());
// find first minute it becomes due
let t = Date.parse('2026-02-28T00:00:00Z');
while (dueReminders([r], t).length === 0) t += 60000;
console.log('scheduler fires at :', new Date(t).toISOString());
console.log('intended UTC        : 2026-03-01T03:30:00.000Z');
console.log('early by hours      :', (r.due_ms - t) / 3600000);
" && npm test 2>&1 | tail -12
